BEGIN;
CREATE TABLE IF NOT EXISTS recovery_state(id INTEGER PRIMARY KEY CHECK(id=1), namespace TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0, confirmed INTEGER NOT NULL DEFAULT 0, confirmed_highwater INTEGER NOT NULL DEFAULT 0, digest TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO recovery_state(id) VALUES(1);
CREATE TRIGGER IF NOT EXISTS recovery_account_insert AFTER INSERT ON accounts BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_account_update AFTER UPDATE ON accounts WHEN OLD.id IS NOT NEW.id OR OLD.email IS NOT NEW.email OR OLD.created_at IS NOT NEW.created_at OR OLD.disabled IS NOT NEW.disabled BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_account_delete AFTER DELETE ON accounts BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_session_revoke AFTER UPDATE OF revoked_at ON sessions WHEN OLD.revoked_at IS NOT NEW.revoked_at BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_device_insert AFTER INSERT ON devices BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_device_identity AFTER UPDATE OF account_id,funti_id,pk,bound_at,name,version ON devices WHEN OLD.account_id IS NOT NEW.account_id OR OLD.funti_id IS NOT NEW.funti_id OR OLD.pk IS NOT NEW.pk OR OLD.bound_at IS NOT NEW.bound_at OR OLD.name IS NOT NEW.name OR OLD.version IS NOT NEW.version BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_device_delete AFTER DELETE ON devices BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_family_insert AFTER INSERT ON family_copies BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_family_update AFTER UPDATE ON family_copies WHEN OLD.device_id IS NOT NEW.device_id OR OLD.revision IS NOT NEW.revision OR OLD.members_json IS NOT NEW.members_json BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_family_delete AFTER DELETE ON family_copies BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_event_insert AFTER INSERT ON events BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_event_update AFTER UPDATE ON events BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_event_delete AFTER DELETE ON events BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_delivery_insert AFTER INSERT ON deliveries BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_delivery_update AFTER UPDATE ON deliveries WHEN OLD.event_id IS NOT NEW.event_id OR OLD.device_id IS NOT NEW.device_id OR OLD.acknowledged_at IS NOT NEW.acknowledged_at BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS recovery_delivery_delete AFTER DELETE ON deliveries BEGIN UPDATE recovery_state SET revision=revision+1 WHERE id=1; END;
PRAGMA user_version=2;
COMMIT;
